return items.map(item => {
  let file = item.json.File;

  if (typeof file !== 'string') {
    return {
      json: {
        ...item.json,
        File: null,
        erro: 'File não é string'
      }
    };
  }

  file = file.trim();

  // remove prefixo data URI
  file = file.replace(/^data:.*;base64,/, '');

  // remove espaços e quebras
  file = file.replace(/\s+/g, '');

  // remove "=" indevido no começo
  file = file.replace(/^=/, '');

  let tipoDetectado = 'desconhecido';

  if (file.startsWith('/9j/')) {
    tipoDetectado = 'jpeg';
  } else if (file.startsWith('iVBOR')) {
    tipoDetectado = 'png';
  } else if (file.startsWith('SUQz')) {
    tipoDetectado = 'mp3';
  } else if (file.startsWith('T2dnUw')) {
    tipoDetectado = 'ogg';
  } else if (file.startsWith('UklGR')) {
    tipoDetectado = 'wav';
  }

  return {
    json: {
      ...item.json,
      File: file,
      tipoDetectado
    }
  };
});

