const items = $items("Edit Fields1", 0);

const seen = new Set();
const resultado = [];

for (const item of items) {
  const numero = item.json.numero;

  // se já viu esse número, ignora
  if (seen.has(numero)) continue;

  // se não viu, adiciona
  seen.add(numero);

  resultado.push({
    json: item.json
  });
}

return resultado;

